def second_largest(nums):
    s = sorted(set(nums), reverse=True)
    return s[1] if len(s) > 1 else None

def rle(s):
    out = []
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        out.append(s[i] + str(j - i))
        i = j
    return ''.join(out)

def balanced(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    st = []
    for c in s:
        if c in '([{':
            st.append(c)
        elif c in pairs:
            if not st or st.pop() != pairs[c]:
                return False
    return not st

def longest_unique(s):
    last = {}
    start = best = 0
    for i, c in enumerate(s):
        if c in last and last[c] >= start:
            start = last[c] + 1
        last[c] = i
        best = max(best, i - start + 1)
    return best

def merge_intervals(intervals):
    out = []
    for a, b in sorted(intervals):
        if out and a <= out[-1][1]:
            out[-1][1] = max(out[-1][1], b)
        else:
            out.append([a, b])
    return out

def coin_ways(coins, amount):
    ways = [1] + [0] * amount
    for c in coins:
        for v in range(c, amount + 1):
            ways[v] += ways[v - c]
    return ways[amount]

def count_islands(grid):
    seen = set()
    h = len(grid)
    w = len(grid[0]) if h else 0
    count = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == '#' and (r, c) not in seen:
                count += 1
                stack = [(r, c)]
                seen.add((r, c))
                while stack:
                    y, x = stack.pop()
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == '#' and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            stack.append((ny, nx))
    return count

def persistence(n):
    steps = 0
    while n >= 10:
        p = 1
        for d in str(n):
            p *= int(d)
        n = p
        steps += 1
    return steps

import heapq

def kth_pair_sum(a, b, k):
    a, b = sorted(a), sorted(b)
    heap = [(a[i] + b[0], i, 0) for i in range(len(a))]
    heapq.heapify(heap)
    for _ in range(k - 1):
        s, i, j = heapq.heappop(heap)
        if j + 1 < len(b):
            heapq.heappush(heap, (a[i] + b[j + 1], i, j + 1))
    return heap[0][0]

def edit_distance(a, b):
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        prev = cur
    return prev[-1]

def min_rooms(meetings):
    events = []
    for s, e in meetings:
        events.append((s, 1))
        events.append((e, -1))
    cur = best = 0
    for _, d in sorted(events, key=lambda t: (t[0], t[1])):
        cur += d
        best = max(best, cur)
    return best

def roman_value(s):
    v = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i, c in enumerate(s):
        if i + 1 < len(s) and v[c] < v[s[i + 1]]:
            total -= v[c]
        else:
            total += v[c]
    return total

from collections import deque

def maze_steps(maze):
    h, w = len(maze), len(maze[0])
    for r in range(h):
        for c in range(w):
            if maze[r][c] == 'S':
                start = (r, c)
    q = deque([(start, 0)])
    seen = {start}
    while q:
        (r, c), d = q.popleft()
        if maze[r][c] == 'E':
            return d
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and maze[nr][nc] != '#' and (nr, nc) not in seen:
                seen.add((nr, nc))
                q.append(((nr, nc), d + 1))
    return -1

def evaluate(expr):
    toks = []
    i = 0
    while i < len(expr):
        c = expr[i]
        if c.isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            toks.append(int(expr[i:j]))
            i = j
        else:
            if c != ' ':
                toks.append(c)
            i += 1
    pos = [0]
    def peek():
        return toks[pos[0]] if pos[0] < len(toks) else None
    def take():
        pos[0] += 1
        return toks[pos[0] - 1]
    def atom():
        t = take()
        if t == '(':
            v = add()
            take()
            return v
        return t
    def mul():
        v = atom()
        while peek() == '*':
            take()
            v *= atom()
        return v
    def add():
        v = mul()
        while peek() in ('+', '-'):
            op = take()
            r = mul()
            v = v + r if op == '+' else v - r
        return v
    return add()

import bisect

def lis_length(nums):
    tails = []
    for x in nums:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

def survivor(n, k):
    r = 0
    for m in range(2, n + 1):
        r = (r + k) % m
    return r + 1

def sudoku_ok(board):
    seen = set()
    for r in range(9):
        for c in range(9):
            d = board[r][c]
            if d == '.':
                continue
            keys = (('r', r, d), ('c', c, d), ('b', r // 3, c // 3, d))
            if any(k in seen for k in keys):
                return False
            seen.update(keys)
    return True

def max_profit(prices):
    hold, sold, rest = float('-inf'), 0, 0
    for p in prices:
        hold, sold, rest = max(hold, rest - p), hold + p, max(rest, sold)
    return int(max(sold, rest))

def ranges(nums):
    out = []
    i = 0
    while i < len(nums):
        j = i
        while j + 1 < len(nums) and nums[j + 1] == nums[j] + 1:
            j += 1
        out.append(str(nums[i]) if i == j else f'{nums[i]}->{nums[j]}')
        i = j + 1
    return out

def diag_sum(m):
    n = len(m)
    total = sum(m[i][i] + m[i][n - 1 - i] for i in range(n))
    if n % 2:
        total -= m[n // 2][n // 2]
    return total

def next_greater(nums):
    out = [-1] * len(nums)
    st = []
    for i, x in enumerate(nums):
        while st and nums[st[-1]] < x:
            out[st.pop()] = x
        st.append(i)
    return out

def paths(grid):
    h, w = len(grid), len(grid[0])
    dp = [0] * w
    dp[0] = 1 if grid[0][0] == '.' else 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == '#':
                dp[c] = 0
            elif c > 0:
                dp[c] += dp[c - 1]
    return dp[-1]

def shift_text(s, k):
    out = []
    for c in s:
        if 'a' <= c <= 'z':
            out.append(chr((ord(c) - 97 + k) % 26 + 97))
        elif 'A' <= c <= 'Z':
            out.append(chr((ord(c) - 65 + k) % 26 + 65))
        else:
            out.append(c)
    return ''.join(out)

def factorize(n):
    out = {}
    p = 2
    while p * p <= n:
        while n % p == 0:
            out[str(p)] = out.get(str(p), 0) + 1
            n //= p
        p += 1
    if n > 1:
        out[str(n)] = out.get(str(n), 0) + 1
    return out
